                      <div className="flex flex-col ml-8 animate-fadeIn">
                        <label className="text-sm font-semibold text-gray-700 mb-2">
                          Health Conditions
                        </label>
                        <input
                          type="text"
                          name="health_conditions"
                          value={petForm.health_conditions}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
