                        <div className="mt-4 relative inline-block">
                          <img
                            src={URL.createObjectURL(petForm.pet_image)}
                            alt="Pet preview"
                            className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200"
                          />
                          <button
                            type="button"
                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center hover:bg-red-600 transition-colors"
                            onClick={() =>
                              setPetForm((prev) => ({
                                ...prev,
                                pet_image: null,
                              }))
                            }
                          >
                            ×
                          </button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 mb-2">
                      Description *
                    </label>
                    <textarea
                      name="description"
                      value={petForm.description}
                      onChange={handleFormChange}
                      rows="4"
                      required
                      className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors resize-none"
                      placeholder="Describe the found pet's appearance, condition, behavior..."
                    />
                  </div>

                  <div className="flex flex-col-reverse sm:flex-row gap-4 mt-8 pt-6 border-t-2 border-gray-100">
                    <button
                      type="button"
                      onClick={() => setActiveTab("dashboard")}
                      className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 hover:border-gray-400 transition-all duration-200"
                    >
                      Cancel Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={submitLoading}
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                    >
                      {submitLoading ? (
                        <span className="flex items-center justify-center gap-2">
                          <svg
                            className="animate-spin h-5 w-5"
                            viewBox="0 0 24 24"
                          >
                            <circle
                              className="opacity-25"
                              cx="12"
                              cy="12"
                              r="10"
                              stroke="currentColor"
                              strokeWidth="4"
                              fill="none"
                            />
                            <path
                              className="opacity-75"
                              fill="currentColor"
                              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                            />
                          </svg>
                          Submitting...
                        </span>
                      ) : (
                        "Report Found Pet"
                      )}
                    </button>
                  </div>
                </form>
              </div>
