                        Loading approved lost pet reports...
                      </p>
                    </div>
                  ) : allLostReports.filter(
                      (r) =>
                        r.report_type === "LOST" &&
                        r.report_status === "ACCEPTED"
                    ).length > 0 ? (
                    allLostReports
                      .filter(
                        (r) =>
                          r.report_type === "LOST" &&
                          r.report_status === "ACCEPTED"
                      )
                      .map((report) => (
                        <div
                          key={report.id}
