                        >
                          <div className="relative h-56 overflow-hidden bg-gradient-to-br from-gray-100 to-gray-200">
                            <img
                              src={report.photo || "/default-pet.png"}
                              alt={report.pet_name}
                              onError={(e) => {
                                e.target.src = "/default-pet.png";
                              }}
                              className="w-full h-full object-cover"
                            />
                            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                              <h3 className="text-white text-xl font-bold">
                                {report.pet_name}
                              </h3>
                            </div>
                          </div>
                          <div className="p-5 space-y-3">
                            <div className="inline-block px-3 py-1 bg-gradient-to-r from-primary-blue to-primary-teal text-white text-sm font-semibold rounded-full">
                              {report.animal_type}
                            </div>
                            <div className="space-y-2">
                              {report.pet_breed && (
                                <p className="text-sm text-gray-600">
                                  <span className="font-semibold">Breed:</span>{" "}
                                  {report.pet_breed}
                                </p>
                              )}
                              {report.pet_location && (
                                <p className="text-sm text-gray-600 flex items-center gap-1">
                                  <span>📍</span>
                                  <span className="font-semibold">
                                    Last Seen:
                                  </span>{" "}
                                  {report.pet_location}
                                </p>
                              )}
                            </div>
                            <p className="text-sm text-gray-700 line-clamp-3">
                              {report.description
                                ? report.description.length > 80
                                  ? `${report.description.substring(0, 80)}...`
                                  : report.description
                                : "No description available"}
                            </p>
                            <div className="flex items-center justify-between pt-3 border-t border-gray-200">
                              <span className="text-xs text-gray-500">
                                {new Date(
                                  report.created_at
                                ).toLocaleDateString()}
                              </span>
                              <span className="text-xs text-gray-500">
                                By: {report.owner_username || "Anonymous"}
                              </span>
                            </div>
                            <div className="inline-block px-3 py-1.5 bg-green-100 text-green-700 text-xs font-bold rounded-lg">
                              ✓ APPROVED - LOST
                            </div>
                            <div className="mt-3 p-3 bg-blue-50 rounded-xl flex items-center gap-2 text-sm text-primary-blue font-medium">
                              <span className="text-xl">📞</span>
                              <span>Contact owner to help reunite</span>
                            </div>
                          </div>
                        </div>
                      ))
                  ) : (
                    <div className="col-span-full text-center py-16">
                      <div className="text-6xl mb-4">🔍</div>
                      <p className="text-gray-500 text-lg">
                        No approved lost pet reports from community members yet
                      </p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "explore-adoption" && (
              <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-xl p-8 border border-blue-100">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    ❤️
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    EXPLORE PETS AVAILABLE FOR ADOPTION (
                    {availableAdoptionPets.length})
                  </span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {loading ? (
                    <div className="col-span-full flex flex-col items-center justify-center py-12">
                      <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-primary-blue mb-4"></div>
                      <p className="text-gray-600">Loading available pets...</p>
                    </div>
                  ) : availableAdoptionPets.length > 0 ? (
                    availableAdoptionPets.map((pet) => (
                      <div
                        key={pet.id}
                        className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 overflow-hidden border border-blue-100"
                      >
                        <div className="relative h-56 overflow-hidden bg-gradient-to-br from-pink-100 to-purple-100">
                          <img
                            src={pet.image || "/default-pet.png"}
                            alt={pet.name}
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                            className="w-full h-full object-cover"
                          />
                          <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                            <h3 className="text-white text-xl font-bold">
                              {pet.name}
                            </h3>
                          </div>
                        </div>
                        <div className="p-5 space-y-3">
                          <div className="inline-block px-3 py-1 bg-gradient-to-r from-primary-blue to-primary-teal text-white text-sm font-semibold rounded-full">
                            {pet.type}
                          </div>
                          <div className="flex flex-wrap gap-2 text-sm text-gray-600">
                            {pet.breed && (
                              <span className="px-2 py-1 bg-gray-100 rounded-lg">
                                {pet.breed}
                              </span>
                            )}
                            <span className="px-2 py-1 bg-gray-100 rounded-lg flex items-center gap-1">
                              🎂 {pet.age} years
                            </span>
                            <span className="px-2 py-1 bg-gray-100 rounded-lg">
                              {pet.gender === "Male" ? "♂️" : "♀️"} {pet.gender}
                            </span>
                            {pet.location && (
                              <span className="px-2 py-1 bg-gray-100 rounded-lg flex items-center gap-1">
                                📍 {pet.location}
                              </span>
                            )}
                          </div>
                          <p className="text-sm text-gray-700 line-clamp-3">
                            {pet.description
                              ? pet.description.length > 100
                                ? `${pet.description.substring(0, 100)}...`
                                : pet.description
                              : "No description available"}
                          </p>
                          <div className="flex flex-wrap gap-2">
                            {pet.is_vaccinated && (
                              <span className="px-2 py-1 bg-green-100 text-green-700 text-xs font-semibold rounded-lg flex items-center gap-1">
                                ✓ Vaccinated
                              </span>
                            )}
                            {pet.is_diseased && (
                              <span className="px-2 py-1 bg-yellow-100 text-yellow-700 text-xs font-semibold rounded-lg flex items-center gap-1">
                                ⚠ Health Condition
                              </span>
                            )}
                          </div>
                          <div className="inline-block w-full px-3 py-1.5 bg-purple-100 text-purple-700 text-xs font-bold rounded-lg text-center">
                            AVAILABLE FOR ADOPTION
                          </div>
                          <div className="pt-2">
                            {pet.has_pending_request ? (
                              <button
                                className="w-full px-4 py-3 bg-gray-300 text-gray-600 font-semibold rounded-xl cursor-not-allowed flex items-center justify-center gap-2"
                                disabled
                              >
                                <span className="text-lg">⏳</span>
                                Request Pending
                              </button>
                            ) : (
                              <button
                                onClick={async () => {
                                  try {
                                    setSubmitLoading(true);
                                    setError("");
                                    await petsAPI.requestAdoption({
                                      pet_id: pet.id,
                                      reason: "I would like to adopt this pet",
                                    });
                                    setSuccessMessage(
                                      "Adoption request submitted! Admin will review your request."
                                    );
                                    await loadData();
                                    setTimeout(
                                      () => setSuccessMessage(""),
                                      3000
                                    );
                                  } catch (err) {
                                    setError(
                                      err.response?.data?.error ||
                                        "Failed to submit adoption request. Please try again."
                                    );
                                  } finally {
                                    setSubmitLoading(false);
                                  }
                                }}
                                disabled={submitLoading}
                                className="w-full px-4 py-3 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center justify-center gap-2"
                              >
                                <span className="text-lg">🐾</span>
                                Request Adoption
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="col-span-full text-center py-16">
                      <div className="text-6xl mb-4">🐾</div>
                      <p className="text-gray-500 text-lg">
                        No pets available for adoption at the moment
                      </p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "post-pet-adoption" && (
              <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-xl p-8 border border-blue-100">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    ➕
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    POST YOUR PET FOR ADOPTION
                  </span>
                </h2>
                <form onSubmit={handlePostPetForAdoption}>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Pet Name *
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.name}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            name: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Enter pet name"
                      />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Pet Type *
                      </label>
                      <select
                        value={postAdoptionForm.type}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            type: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors bg-white"
                      >
                        <option value="">Select Type</option>
                        <option value="Dog">Dog</option>
                        <option value="Cat">Cat</option>
                        <option value="Bird">Bird</option>
                        <option value="Rabbit">Rabbit</option>
                        <option value="Other">Other</option>
                      </select>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Breed
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.breed}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            breed: e.target.value,
                          })
                        }
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Enter breed"
                      />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Age (years) *
                      </label>
                      <input
                        type="number"
                        min="0"
                        value={postAdoptionForm.age}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            age: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Age in years"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Gender *
                      </label>
                      <select
                        value={postAdoptionForm.gender}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            gender: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors bg-white"
                      >
                        <option value="">Select Gender</option>
                        <option value="Male">Male</option>
                        <option value="Female">Female</option>
                      </select>
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Location *
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.location}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            location: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Current location"
                      />
                    </div>
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 mb-2">
                      Description
                    </label>
                    <textarea
                      rows="4"
                      value={postAdoptionForm.description}
                      onChange={(e) =>
                        setPostAdoptionForm({
                          ...postAdoptionForm,
                          description: e.target.value,
                        })
                      }
                      className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors resize-none"
                      placeholder="Describe your pet's temperament, habits, and why they're great for adoption..."
                    />
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 mb-2">
                      Pet Image
                    </label>
                    <input
                      type="file"
                      accept="image/*"
                      onChange={(e) =>
                        setPostAdoptionForm({
                          ...postAdoptionForm,
                          image: e.target.files[0],
                        })
                      }
                      className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                    />
                  </div>

                  <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <span className="text-2xl">💊</span>
                    Medical Information
                  </h3>

                  <div className="space-y-4 mb-6">
                    <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-xl hover:bg-gray-100 transition-colors">
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_vaccinated}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_vaccinated: e.target.checked,
                          })
                        }
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 cursor-pointer select-none">
                        Is Vaccinated
                      </label>
                    </div>

                    {postAdoptionForm.is_vaccinated && (
                      <div className="ml-8 space-y-4 animate-fadeIn">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div className="flex flex-col">
                            <label className="text-sm font-semibold text-gray-700 mb-2">
                              Vaccination Date
                            </label>
                            <input
                              type="date"
                              value={postAdoptionForm.vaccination_date}
                              onChange={(e) =>
                                setPostAdoptionForm({
                                  ...postAdoptionForm,
                                  vaccination_date: e.target.value,
                                })
                              }
                              className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                            />
                          </div>
                          <div className="flex flex-col">
                            <label className="text-sm font-semibold text-gray-700 mb-2">
                              Vaccination Type
                            </label>
                            <input
                              type="text"
                              value={postAdoptionForm.vaccination_type}
                              onChange={(e) =>
                                setPostAdoptionForm({
                                  ...postAdoptionForm,
                                  vaccination_type: e.target.value,
                                })
                              }
                              className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                              placeholder="e.g., Rabies, DHPP"
                            />
                          </div>
                        </div>
                        <div className="flex flex-col">
                          <label className="text-sm font-semibold text-gray-700 mb-2">
                            Vaccination Certificate
                          </label>
                          <input
                            type="file"
                            accept=".pdf,.jpg,.jpeg,.png"
                            onChange={(e) =>
                              setPostAdoptionForm({
                                ...postAdoptionForm,
                                vaccination_certificate: e.target.files[0],
                              })
                            }
                            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                          />
                          <p className="text-xs text-gray-500 mt-2">
                            Upload PDF or image file
                          </p>
                        </div>
                      </div>
                    )}

                    <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-xl hover:bg-gray-100 transition-colors">
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_diseased}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_diseased: e.target.checked,
                          })
                        }
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 cursor-pointer select-none">
                        Has Health Conditions
                      </label>
                    </div>

                    {postAdoptionForm.is_diseased && (
                      <div className="ml-8 flex flex-col animate-fadeIn">
                        <label className="text-sm font-semibold text-gray-700 mb-2">
                          Health Condition Description
                        </label>
                        <textarea
                          rows="3"
                          value={postAdoptionForm.disease_description}
                          onChange={(e) =>
                            setPostAdoptionForm({
                              ...postAdoptionForm,
                              disease_description: e.target.value,
                            })
                          }
                          className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors resize-none"
                          placeholder="Describe any health conditions or special care needs..."
                        />
                      </div>
                    )}
                  </div>

                  <button
                    type="submit"
                    disabled={submitLoading}
                    className="w-full px-6 py-4 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                  >
                    {submitLoading ? (
                      <span className="flex items-center justify-center gap-2">
                        <svg
                          className="animate-spin h-5 w-5"
                          viewBox="0 0 24 24"
                        >
                          <circle
                            className="opacity-25"
                            cx="12"
                            cy="12"
                            r="10"
                            stroke="currentColor"
                            strokeWidth="4"
                            fill="none"
                          />
                          <path
                            className="opacity-75"
                            fill="currentColor"
                            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                          />
                        </svg>
                        Posting...
                      </span>
                    ) : (
                      "Post Pet for Adoption"
                    )}
                  </button>
                </form>
              </div>
            )}

            {activeTab === "my-adoption-posts" && (
              <div className="my-adoption-posts-section">
                <div className="section-header">
                  <span className="material-icons">article</span>
                  MY ADOPTION POSTS ({myAdoptionPosts.length})
                </div>
                <div className="reports-grid">
                  {loading ? (
                    <div className="loading">
                      Loading your adoption posts...
                    </div>
                  ) : myAdoptionPosts.length > 0 ? (
                    myAdoptionPosts.map((post) => (
                      <div
                        key={post.id}
                        className="dashboard-pet-card my-adoption-post"
                      >
                        <div className="pet-card-image">
                          <img
                            src={post.image || "/default-pet.png"}
                            alt={post.name}
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                          />
                          <div className="pet-name-overlay">
                            <h3>{post.name}</h3>
                          </div>
                        </div>
                        <div className="pet-card-info">
                          <div className="pet-type">{post.type}</div>
                          <div className="pet-details">
                            {post.breed && (
                              <span className="pet-breed">{post.breed}</span>
                            )}
                            <span className="pet-age">
                              🎂 {post.age} years old
                            </span>
                            <span className="pet-gender">
                              {post.gender === "Male" ? "♂️" : "♀️"}{" "}
                              {post.gender}
                            </span>
                            {post.location && (
                              <span className="pet-location">
                                📍 {post.location}
                              </span>
                            )}
                          </div>
                          <div className="pet-description">
                            {post.description
                              ? post.description.length > 100
                                ? `${post.description.substring(0, 100)}...`
                                : post.description
                              : "No description available"}
                          </div>
                          <div className="pet-medical-info">
                            {post.is_vaccinated && (
                              <span className="badge vaccinated">
                                ✓ Vaccinated
                              </span>
                            )}
                            {post.is_diseased && (
                              <span className="badge health-issue">
                                ⚠ Health Condition
                              </span>
                            )}
                          </div>
                          <div
                            className={`pet-status-badge status-${post.report_status}`}
                          >
                            {post.report_status === "pending" &&
                              "⏳ PENDING ADMIN REVIEW"}
                            {post.report_status === "accepted" &&
                              "✅ APPROVED - LIVE"}
                            {post.report_status === "rejected" && "❌ REJECTED"}
                          </div>
                          {post.admin_comment && (
                            <div className="admin-comment">
                              <strong>Admin Comment:</strong>{" "}
                              {post.admin_comment}
                            </div>
                          )}
                          <div className="post-date">
                            Posted:{" "}
                            {new Date(post.created_at).toLocaleDateString()}
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="no-reports">
                      <span className="material-icons">article</span>
                      <p>You haven't posted any pets for adoption yet</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "profile" && (
              <div className="profile-section-content">
                <div className="section-header">
                  <span className="material-icons">person</span>
                  PROFILE MANAGEMENT
                </div>

                <div className="profile-container">
                  <div className="profile-image-section">
                    <div className="profile-image-large">
                      {profileImagePreview ? (
                        <img
                          src={profileImagePreview}
                          alt="Profile"
                          className="profile-image-display"
                        />
                      ) : (
                        <div className="profile-image-placeholder-large">
                          <span className="material-icons">person</span>
                        </div>
                      )}
                    </div>

                    {isEditingProfile && (
                      <div className="image-upload-section">
                        <label
                          htmlFor="profile-image-input"
                          className="upload-btn"
                        >
                          <span className="material-icons">photo_camera</span>
                          Change Photo
                        </label>
                        <input
                          id="profile-image-input"
                          type="file"
                          accept="image/*"
                          onChange={handleProfileImageChange}
                          style={{ display: "none" }}
                        />
                      </div>
                    )}
                  </div>

                  <div className="profile-details">
                    <div className="profile-header">
                      <h3>
                        {profileData.first_name}{" "}
                        {profileData.last_name || user?.username}
                      </h3>
                      <p className="user-email">{profileData.email}</p>

                      {!isEditingProfile ? (
                        <button
                          className="btn-edit-profile"
                          onClick={() => setIsEditingProfile(true)}
                        >
                          <span className="material-icons">edit</span>
                          Edit Profile
                        </button>
                      ) : (
                        <div className="edit-profile-actions">
                          <button
                            className="btn-save-profile"
                            onClick={handleProfileSubmit}
                            disabled={submitLoading}
                          >
                            <span className="material-icons">save</span>
                            {submitLoading ? "Saving..." : "Save Changes"}
                          </button>
                          <button
                            className="btn-cancel-profile"
                            onClick={() => {
                              setIsEditingProfile(false);
                              setProfileImage(null);
                              setProfileImagePreview(
                                profileData.profile_picture
                              );
                            }}
                          >
                            <span className="material-icons">cancel</span>
                            Cancel
                          </button>
                        </div>
                      )}
                    </div>

                    {isEditingProfile ? (
                      <form
                        onSubmit={handleProfileSubmit}
                        className="profile-edit-form"
                      >
                        <div className="form-row">
                          <div className="form-group">
                            <label>First Name</label>
                            <input
                              type="text"
                              name="first_name"
                              value={profileData.first_name}
                              onChange={handleProfileInputChange}
                              placeholder="Enter first name"
                            />
                          </div>
                          <div className="form-group">
                            <label>Last Name</label>
                            <input
                              type="text"
                              name="last_name"
                              value={profileData.last_name}
                              onChange={handleProfileInputChange}
                              placeholder="Enter last name"
                            />
                          </div>
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>Email</label>
                            <input
                              type="email"
                              name="email"
                              value={profileData.email}
                              onChange={handleProfileInputChange}
                              placeholder="Enter email address"
                            />
                          </div>
                          <div className="form-group">
                            <label>Phone Number</label>
                            <input
                              type="tel"
                              name="phone_no"
                              value={profileData.phone_no}
                              onChange={handleProfileInputChange}
                              placeholder="Enter phone number"
                            />
                          </div>
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>City</label>
                            <input
                              type="text"
                              name="city"
                              value={profileData.city}
                              onChange={handleProfileInputChange}
                              placeholder="Enter city"
                            />
                          </div>
                          <div className="form-group">
                            <label>State</label>
                            <input
                              type="text"
                              name="state"
                              value={profileData.state}
                              onChange={handleProfileInputChange}
                              placeholder="Enter state"
                            />
                          </div>
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>PIN Code</label>
                            <input
                              type="text"
                              name="pincode"
                              value={profileData.pincode}
                              onChange={handleProfileInputChange}
                              placeholder="Enter PIN code"
                            />
                          </div>
                          <div className="form-group">
                            <label>Gender</label>
                            <select
                              name="gender"
                              value={profileData.gender}
                              onChange={handleProfileInputChange}
                            >
                              <option value="">Select Gender</option>
                              <option value="Male">Male</option>
                              <option value="Female">Female</option>
                              <option value="Other">Other</option>
                            </select>
                          </div>
                        </div>

                        <div className="form-group full-width">
                          <label>Address</label>
                          <textarea
                            name="address"
                            value={profileData.address}
                            onChange={handleProfileInputChange}
                            placeholder="Enter complete address"
                            rows="3"
                          />
                        </div>
                      </form>
                    ) : (
                      <div className="profile-view">
                        <div className="profile-info-grid">
                          <div className="info-item">
                            <span className="info-label">Phone:</span>
                            <span className="info-value">
                              {profileData.phone_no || "Not provided"}
                            </span>
                          </div>
                          <div className="info-item">
                            <span className="info-label">City:</span>
                            <span className="info-value">
                              {profileData.city || "Not provided"}
                            </span>
                          </div>
                          <div className="info-item">
                            <span className="info-label">State:</span>
                            <span className="info-value">
                              {profileData.state || "Not provided"}
                            </span>
                          </div>
                          <div className="info-item">
                            <span className="info-label">PIN Code:</span>
                            <span className="info-value">
                              {profileData.pincode || "Not provided"}
                            </span>
                          </div>
                          <div className="info-item">
                            <span className="info-label">Gender:</span>
                            <span className="info-value">
                              {profileData.gender || "Not provided"}
                            </span>
                          </div>
                          <div className="info-item full-width">
                            <span className="info-label">Address:</span>
                            <span className="info-value">
                              {profileData.address || "Not provided"}
                            </span>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}
          </main>
        </div>
      </div>
    </div>
  );
};

export default UserDashboard;
